import org.junit.jupiter.api.Test;
import reactor.core.publisher.Flux;
import reactor.test.StepVerifier;

class FluxTest {

    @Test
    void emet_les_valeurs_filtrees() {
        Flux<Integer> flux = Flux.just(1, 2, 3).filter(n -> n > 1);
        StepVerifier.create(flux)
            .expectNext(2, 3)
            .verifyComplete();
    }
}
